-- ACIM books: every chapter, section and lesson, linked to the original — BodyTalk Protocol Navigator
-- Owner's request (2026-09-26): inside each ACIM book, all chapters, each with a
-- link to the original at the Foundation for Inner Peace.
-- Source: the official table of contents served by acim.org
-- (https://acim.org/we-api/en/toc, read 2026-09-26). Titles are copied from it
-- as they are; nothing is written from memory. Links use the site's own page
-- address, https://acim.org/acim/<slugs>/en/s/<section id>; a group (chapter,
-- part, review) links to its first page. Sample links were opened and checked.
-- Structure mirrors the site: Text → chapters → sections; Workbook → Part I /
-- Part II → lesson groups and reviews → lessons (361–365 are one entry, as on
-- the site); Manual for Teachers → sections and Clarification of Terms; The
-- Song of Prayer → 3 chapters → sections. 788 rows.
-- Applied to production on 2026-09-26.

update dim_protocol_node set child_tab_label='Contents' where code in ('ACIM.1','ACIM.2','ACIM.3','ACIM.4');
update dim_protocol_node set link_url='https://acim.org/acim/en', sources='A Course in Miracles, Foundation for Inner Peace (acim.org).' where code='ACIM';

on conflict (code) do update set parent_code=excluded.parent_code, name=excluded.name, level=excluded.level,
  sort_order=excluded.sort_order, child_tab_label=excluded.child_tab_label, link_url=excluded.link_url, sources=excluded.sources;
